const {records, owners} = await ctx.call("records", {});
const totals = {Ada: 0, Bo: 0, Cy: 0};
const entries = Array.isArray(owners) ? owners : Object.entries(owners).map(([group, owner]) => ({group, owner}));
for (const record of records) {
  if (record.active) {
    const match = entries.find(entry => (typeof entry === "string" ? entry : entry.group) === record.group);
    const name = typeof match === "string" ? match : match?.name ?? match?.owner;
    if (Object.hasOwn(totals, name)) totals[name] += record.value;
  }
}
ctx.done(totals);
